 "content": "def transform(grid):
    """Combine foreground marks from equal panels split by a solid row."""
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid)
                    if len(set(row)) == 1 and r > 0 and r < h - 1), None)
    if divider is None:
        raise ValueError("solid horizontal divider not found")
    top, bottom = grid[:divider], grid[divider + 1:]
    if len(top) != len(bottom) or any(len(row) != w for row in grid):
        raise ValueError("panels must have equal dimensions")
    common = set(v for row in top for v in row) & set(v for row in bottom for v in row)
    if len(common) != 1:
        raise ValueError("expected one shared background color")
    background = common.pop()
    return [[9 if top[r][c] != background or bottom[r][c] != background else 3
             for c in range(w)] for r in range(len(top))]


